class Produk {
  constructor(nama, harga, diskon) {
    this.nama = nama;
    this.harga = harga;
    this.diskon = diskon;
  }
  get hargaAkhir() {
    return this.harga - (this.harga * this.diskon) / 100;
  }
}
const p = new Produk("Sepatu", 300000, 20);
console.log(`${p.nama}: ${p.harga} jadi ${p.hargaAkhir}`);
p.diskon = 50;
console.log(`${p.nama}: ${p.harga} jadi ${p.hargaAkhir}`);
